begin;
create function pg_temp.check_true(ok boolean,description text) returns void language plpgsql as $$begin if ok is not true then raise exception 'Suite test: %',description;end if;end $$;
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000000001','suite-admin@example.test');
insert into public.social_admins(user_id,email,role,is_active,first_name,last_name,username,suite_role_key,access_areas) values ('00000000-0000-4000-8000-000000000001','suite-admin@example.test','admin',true,'Anna','Admin','admia','admin',array['social_media']);
select pg_temp.check_true((select count(*)=17 from public.social_admins where first_name<>'' and user_id<>'00000000-0000-4000-8000-000000000001'),'import names');
select pg_temp.check_true(not has_table_privilege('authenticated','public.social_suite_roles','select'),'private role templates');
select pg_temp.check_true(not has_function_privilege('authenticated','public.suite_users_request(uuid,jsonb)','execute'),'browser cannot call admin RPC');
select pg_temp.check_true(not has_function_privilege('anon','public.suite_brand_request(uuid,jsonb)','execute'),'browser cannot write brand');
select pg_temp.check_true(has_table_privilege('anon','public.social_brand_settings','select') and not has_table_privilege('anon','public.social_brand_settings','update'),'public colors are read only');
select pg_temp.check_true((select username='admin' and first_name='' and last_name='' and is_active and cardinality(access_areas)=9 from public.social_admins where email='admin@example.test'),'legacy shared admin and areas preserved');
set local role service_role;
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001','{"action":"save_member","userId":"00000000-0000-4000-8000-000000000020","roleKey":"admin","username":"admin","firstName":"","lastName":"","extraAreas":[]}')->>'ok')='true','shared account rights editable without inventing personal names');
select pg_temp.check_true((select public.suite_users_request(suite_user_id,'{"action":"roles"}') ->> 'status'='403' from private.cashbook_accounts where username='jentm'),'trainer cannot manage roles');
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001','{"action":"save_role","key":"admin","accessAreas":[]}')->>'status')='403','protected admin');
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001','{"action":"save_role","key":"trainer","accessAreas":["user_management"]}')->>'status')='403','no delegated administration');
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001','{"action":"bulk_state","operation":"block","userIds":["00000000-0000-4000-8000-000000000001"]}')->>'status')='403','self block prevented');
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001','{"action":"save_member","userId":"00000000-0000-4000-8000-000000000001","roleKey":"trainer","firstName":"Anna","lastName":"Admin","username":"admia","extraAreas":[]}')->>'status')='403','self demotion prevented');
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001',jsonb_build_object('action','save_member','userId',suite_user_id,'roleKey','trainer','firstName','Michael','lastName','Jentsch','username','jentm','extraAreas',jsonb_build_array('editorial')))->>'ok')='true','add personal permission') from private.cashbook_accounts where username='jentm';
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001','{"action":"save_role","key":"trainer","accessAreas":["cashbook","club_crests"]}')->>'ok')='true','save role');
select pg_temp.check_true((select access_areas @> array['cashbook','club_crests','editorial'] and extra_access_areas=array['editorial']::text[] from public.social_admins where username='jentm'),'role updates preserve additive permissions');
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001','{"action":"save_role","key":"trainer","accessAreas":["cashbook"]}')->>'ok')='true','remove role right');
select pg_temp.check_true((select access_areas @> array['cashbook','editorial'] and not ('club_crests'=any(access_areas)) from public.social_admins where username='jentm'),'role revocation reflected immediately');
select pg_temp.check_true((public.suite_users_request(suite_user_id,'{"action":"identity"}')->>'firstName')='Michael','personal profile') from private.cashbook_accounts where username='jentm';
select pg_temp.check_true((public.suite_cashbook_login('{"action":"attempt","username":"AdMiA"}')->>'email')='suite-admin@example.test','username login for ordinary suite account');
select public.suite_cashbook_login('{"action":"attempt","username":"admia"}') from generate_series(1,4);
select pg_temp.check_true((public.suite_cashbook_login('{"action":"attempt","username":"admia"}')->>'status')='429','login limiter');
select public.suite_cashbook_login('{"action":"success","username":"admia"}');
select pg_temp.check_true((public.suite_cashbook_login('{"action":"attempt","username":"admia"}')->>'email')='suite-admin@example.test','successful login resets attempts');
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001',jsonb_build_object('action','bulk_state','operation','block','userIds',jsonb_build_array(suite_user_id)))->>'ok')='true','block') from private.cashbook_accounts where username='jentm';
select pg_temp.check_true((public.suite_users_request(suite_user_id,'{"action":"identity"}')->>'status')='403','old session profile denied') from private.cashbook_accounts where username='jentm';
select pg_temp.check_true((public.cashbook_request(suite_user_id,'{"action":"load"}')->>'status')='403','old session cashbook denied') from private.cashbook_accounts where username='jentm';
select pg_temp.check_true((public.suite_cashbook_login('{"action":"attempt","username":"jentm"}')->>'status')='403','blocked alias denied');
select public.suite_users_request('00000000-0000-4000-8000-000000000001',jsonb_build_object('action','bulk_state','operation','activate','userIds',jsonb_build_array(suite_user_id))) from private.cashbook_accounts where username='jentm';
select pg_temp.check_true((select is_active and not is_blocked from public.social_admins where username='jentm'),'activate clears block');
select pg_temp.check_true((public.suite_users_request('00000000-0000-4000-8000-000000000001',jsonb_build_object('action','bulk_state','operation','block','userIds',jsonb_build_array(suite_user_id,'00000000-0000-4000-8000-000000000099')))->>'status')='409','stale selection rejected atomically') from private.cashbook_accounts where username='jentm';
select pg_temp.check_true((select is_active from public.social_admins where username='jentm'),'stale batch did not block existing account');
update private.cashbook_accounts set username='jentsm' where username='jentm';
select pg_temp.check_true((select username='jentsm' from public.social_admins where first_name='Michael'),'cashbook and suite aliases synchronized');
select pg_temp.check_true((public.suite_brand_request(suite_user_id,jsonb_build_object('colorScheme',(select color_scheme from public.social_brand_settings)))->>'status')='403','trainer cannot edit brand') from private.cashbook_accounts where username='jentsm';
update public.social_teams set color_source='custom',color_scheme='{"panel":"#123456"}' where slug='u19-junioren';
select pg_temp.check_true((public.suite_brand_request('00000000-0000-4000-8000-000000000001',jsonb_build_object('colorScheme',(select color_scheme||'{"panel":"#123abc"}'::jsonb from public.social_brand_settings))) ? 'teams'),'brand saved');
select pg_temp.check_true((select bool_and(color_scheme->>'panel'='#123abc') from public.social_teams where color_source='global'),'global teams inherit standard');
select pg_temp.check_true((select color_scheme->>'panel'='#123456' from public.social_teams where slug='u19-junioren'),'custom team colors preserved');
reset role;
rollback;
